//[group=BaatDiagramScripts]
!INC Local Scripts.EAConstants-JavaScript
!INC EAScriptLib.JavaScript-Dialog
!INC BaatScriptLib.BaatScript-Logging
!INC BaatScriptLib.DiagramAnalysisLayoutCommon

/*
 * Script Name:	DiagramAnalysisLayout
 * Author:		J de Baat
 * Purpose:		Dynamically draw elements on the diagram as indicated by the TaggedValues defined in the selected element
 * Date:		20-12-2024
 *
 * This script takes a number of selected elements on a diagram to start the analysis.
 * For each selected element on a diagram
 *   If the Keywords property of the element contains the DALKeywordsTag
 *     Collect all referenced elements to a set for the first level
 *     Process the current level for all elements in the set:
 *       For each referenced element in the set
 *         If element not yet drawn on the diagram
 *           Draw the element on the indicated location of the diagram
 *           Collect all referenced elements to a set for the next level
 *       Recursively process the set of elements found
 *
 */

/*
 * Diagram Script main function
 */
function DiagramAnalysisLayout()
{
	// Show the script output window
	Repository.EnsureOutputVisible( "Script" );

	Session.Output( "======================================= Started DiagramAnalysisLayout at " + _BLOGGetDisplayDate() + "!" );

	// Get a reference to objGlobalDALDiagram
	objGlobalDALDiagram = Repository.GetCurrentDiagram();

	if ( objGlobalDALDiagram != null )
	{
		// Get a reference to any selected objects
		var selectedElement as EA.Element;
		var selectedObjects as EA.Collection;
		selectedObjects      = objGlobalDALDiagram.SelectedObjects;

		try
		{

			if ( selectedObjects.Count > 0 )
			{
				BLOGDebug("DiagramAnalysisLayout: Selected selectedObjects.Count: " + selectedObjects.Count );

				// One or more diagram objects are selected
				let selectedObjectsCount = selectedObjects.Count;
				for ( var i = 0 ; i < selectedObjectsCount ; i++ )
				{
					// Process the currentDiagramElement
					var currentDiagramElement as EA.Element;
					var currentElement        as EA.Element;
					currentDiagramElement      = selectedObjects.GetAt( i );
					currentElement             = Repository.GetElementByID( currentDiagramElement.ElementID );

					// Process the currentElement for DiagramAnalysisLayout
					DALProcessElement( currentElement );
				}

				// Reload objGlobalDALDiagram when all processing is done
				Repository.ReloadDiagram( objGlobalDALDiagram.DiagramID );

			}
			else
			{
				// Nothing is selected
				BLOGError( "This script requires at least one element to be selected!" );
			}
		}
		catch (catch_err)
		{
			BLOGError("DiagramAnalysisLayout found Error: " + catch_err.message + "!!!" );
		}

		Session.Output( "======================================= Finished DiagramAnalysisLayout at " + _BLOGGetDisplayDate() + "!" );
	}
	else
	{
		Session.Prompt( "This script requires a diagram to be visible.", promptOK);
	}
}

DiagramAnalysisLayout();

//[group=BaatDiagramScripts]
!INC Local Scripts.EAConstants-JavaScript
!INC BaatScriptLib.BaatScript-Logging

/*
 * This code has been included from the default Diagram Script template.
 *
 * For all LegendElements on the selected diagram:
 *   If TaggedValue filter
 *      Find all TaggedValues for this Value
 *      Update t_xref list of properties for this legend
 *   Refresh Diagram
 *
 *
 * Script Name: RefreshDynamicLegend
 * Author:      J de Baat
 * Purpose:     Refresh the set of color definitions of all legend elements supporting all values occuring on the selected diagram
 * Date:        20-12-2024
 */

// The level to log at
var   BLOGLEVEL = BLOGLEVEL_WARNING;		// Choose from: BLOGLEVEL_ERROR, BLOGLEVEL_WARNING, BLOGLEVEL_INFO, BLOGLEVEL_DEBUG, BLOGLEVEL_TRACE

/*
 * A list of colors to use for generating the list of legend values
 * Hexadecimal to Decimal converter via https://www.rapidtables.com/convert/number/hex-to-decimal.html
 */
var legendColors =[ "1029550",		// #0FB5AE
            "4212426",		// #4046CA
            "16155921",		// #F68511
            "14564738",		// #DE3D82
            "8291578",		// #7E84FA
            "7528554",		// #72E06A
            "1342195",		// #147AF3
            "7546579",		// #7326D3
            "15255040",		// #E8C600
            "13327616",		// #CB5D00
            "36701",		// #008F5D
            "12380465",		// #BCE931
            "0"				// #black
];

/*
 * Test whether an element is a Legend
 */
function ElementIsLegend( theElement )
{
	// Cast theElement to EA.Element so we get intellisense
	var inputElement as EA.Element;
	inputElement      = theElement;

	return ( (inputElement.ObjectType == 4) && (inputElement.Subtype == 76) );

}

/*
 * Get the filter value for the LegendElement
 */
function GetLegendFilter( theElement )
{
	// Cast theElement to EA.Element so we get intellisense
	var inputElement as EA.Element;
	inputElement      = theElement;

	// Find the TaggedValue in the string of format "*LegendTypeObj=Filter=" + "TaggedValue." + strLegendTaggedValue + ":;*"
	var strLegendTaggedValue01 = inputElement.StyleEx.split("LegendTypeObj=Filter=");
	var strLegendTaggedValue02 = strLegendTaggedValue01[1].split(":;");
	var strLegendTaggedValue03 = strLegendTaggedValue02[0].split(".");
	if ( strLegendTaggedValue03[0] == "TaggedValue" )
	{
		// Check for strLegendTaggedValue to be of format strLegendValue + ":AppliesTo=*"
		var strLegendTaggedValue04 = strLegendTaggedValue03[1].split(":AppliesTo=");
		return strLegendTaggedValue04[0];
	}
	return false;

}

/*
 * Get all values for theTaggedValueProperty from the t_objectproperties table
 */
function GetLegendTaggedValuesForProperty( theTaggedValueProperty )
{

	// Get all the TaggedValues registered for theTaggedValueProperty
	var strSQLQuery = "select distinct t_objectproperties.Value as TaggedValues from t_objectproperties"
                      + " where t_objectproperties.Property = '" + theTaggedValueProperty + "'"
                      + " order by t_objectproperties.Value";
	var sqlResponse = Repository.SQLQuery( strSQLQuery );

	// Convert the sqlResponse from XML to an array of TaggedValues
	var arrResponse = convertXMLtoTagNameArray( sqlResponse, "TaggedValues" );

	return arrResponse;

}

/*
 * Extract an array from the XML resultset of an SQLQuery based on the xmlTagName
 */
function convertXMLtoTagNameArray( xmlString, xmlTagName )
{

	var xmlDOM = new COMObject( "MSXML2.DOMDocument" );
	xmlDOM.validateOnParse = false;
	xmlDOM.async = false;
	if ( xmlDOM.loadXML( xmlString ) ){
		var nodeList = xmlDOM.documentElement.selectNodes( '//' + xmlTagName );
		if ( nodeList.length > 0 ) {
			return nodeList;
		}
	}

	return false;

}

/*
 * Update the Description value for the LegendElement in the t_xref table
 */
function updateLegendElementXRef( theElement, theLegendDescription )
{

	// Cast theElement to EA.Element so we get intellisense
	var inputElement as EA.Element;
	inputElement = theElement;

	// Get all the TaggedValues registered for theTaggedValueProperty
	var strSQLQuery = "update t_xref set Description = '" + theLegendDescription + "'"
                      + " where Name = 'CustomProperties'"
                      + " and Type = 'element property'"
                      + " and Client = '" + inputElement.ElementGUID + "'";
	var sqlResponse = Repository.Execute( strSQLQuery );

	return true;

	// TODO: Check sqlResponse as result of Repository.Execute
	//Session.Output("strSQLQuery ==> Resulted in: " + sqlResponse );
	//return sqlResponse;

}

/*
 * Make a new property string for the theValueName and theValueIndex
 */
function getLegendPropString( theValueName, theValueIndex )
{

	var strPropOutput = "";

	strPropOutput += "@PROP=";
	strPropOutput += "@NAME=";
	strPropOutput += theValueName;
	strPropOutput += "@ENDNAME;";
	strPropOutput += "@TYPE=LEGEND_OBJECTSTYLE@ENDTYPE;";
	strPropOutput += "@VALU=#Back_Ground_Color#=";
	strPropOutput += legendColors[theValueIndex % legendColors.length ];
	strPropOutput += ";";
	strPropOutput += "#Pen_Color#=0;";
	strPropOutput += "#Pen_Size#=1;";
	strPropOutput += "#Legend_Type#=LEGEND_OBJECTSTYLE;";
	strPropOutput += "@ENDVALU;";
	strPropOutput += "@PRMT=";
	strPropOutput += theValueIndex;
	strPropOutput += "@ENDPRMT;";
	strPropOutput += "@ENDPROP;";

	return strPropOutput;

}

/*
 * Make a new property string for theLegendName and theLegendTitle
 */
function getLegendStyleSetting( theLegendName, theLegendTitle )
{

	var strPropOutput = "";

	strPropOutput += "@PROP=";
	strPropOutput += "@NAME=";
	strPropOutput += theLegendName;
	strPropOutput += "@ENDNAME;";
	strPropOutput += "@TYPE=LEGEND_STYLE_SETTINGS@ENDTYPE;";
	strPropOutput += "@VALU=#TITLE#=";
	strPropOutput += theLegendTitle;
	strPropOutput += ";";
	strPropOutput += "@ENDVALU;";
	strPropOutput += "@PRMT=";
	strPropOutput += "@ENDPRMT;";
	strPropOutput += "@ENDPROP;";

	return strPropOutput;

}

/*
 * Process a LegendElement provided as parameter
 */
function ProcessLegendElement( theElement )
{

	// Cast theElement to EA.Element so we get intellisense
	var inputElement as EA.Element;
	currentElement    = theElement;

	// Check whether the currentElement is a Legend
	if ( ElementIsLegend( currentElement ) )
	{
		var strLegendFilterProperty = "";
		var strLegendTaggedValues   = "";
		var strLegendProperty       = "";

		strLegendFilterProperty = GetLegendFilter( currentElement );
		strLegendTaggedValues   = GetLegendTaggedValuesForProperty( strLegendFilterProperty );

		// Process the strLegendTaggedValues found
		if ( strLegendTaggedValues.length > 0 ) {

			// Add all getLegendPropString found for all strLegendTaggedValues
			for ( var i = 0 ; i < strLegendTaggedValues.length ; i++ ) {
				strLegendProperty += getLegendPropString( strLegendTaggedValues.item(i).text, i );
			}

			// Add the getLegendStyleSetting found
			strLegendProperty += getLegendStyleSetting( currentElement.Name, currentElement.Name );

			// Refresh the currentElement and Update the currentDiagram to reflect the changes
			var boolResult = updateLegendElementXRef( currentElement, strLegendProperty );
			if ( boolResult ) {
				Session.Output("Legend(" + currentElement.Name + ") UPDATED successfully!!!" );
			} else {
				Session.Output("Legend(" + currentElement.Name + ") update NOT successful!!!" );
			}
		} else {
			Session.Output("Legend(" + currentElement.Name + ") found NO valid strLegendTaggedValues!!!" );
		}
	}

}

/*
 * Diagram Script main function
 */
function RefreshDynamicLegend()
{

	// Show the script output window
	Repository.EnsureOutputVisible( "Script" );

	Session.Output( "======================================= Started RefreshDynamicLegend at " + _BLOGGetDisplayDate() + "!" );

	try
	{

		// Get a reference to the current diagram
		var currentDiagram as EA.Diagram;
		currentDiagram      = Repository.GetCurrentDiagram();

		if ( currentDiagram != null )
		{
			BLOGInfo("Selected Diagram(DiagramID: " + currentDiagram.DiagramID + ") Name= " + currentDiagram.Name );

			// Get a reference to any selected connector/objects
			var diagramObjects as EA.Collection;
			var currentElement as EA.Element;
			diagramObjects      = currentDiagram.DiagramObjects;

			// Check whether this diagram has any objects in it
			if ( diagramObjects.Count > 0 )
			{
				BLOGInfo("Selected diagramObjects.Count: " + diagramObjects.Count );
				// One or more diagram objects are selected
				let diagramObjectsCount = diagramObjects.Count;
				for ( var i = 0 ; i < diagramObjectsCount ; i++ )
				{
					// Process the currentDiagramElement
					var currentDiagramElement as EA.Element;
					var currentElement        as EA.Element;
					currentDiagramElement      = diagramObjects.GetAt( i );
					currentElement             = Repository.GetElementByID( currentDiagramElement.ElementID );

					// Process the currentElement when it is a Legend
					ProcessLegendElement( currentElement );
				}

				// Reload diagram when all processing is done
				Repository.ReloadDiagram( currentDiagram.DiagramID );
			}
			else
			{
				// No objects on this diagram
				BLOGError("No objects on this diagram" );
			}
		}
		else
		{
			Session.Prompt( "This script requires a diagram to be visible.", promptOK)
		}
	}
	catch(catch_err)
	{
		BLOGError("RefreshDynamicLegend found Error: " + catch_err + "!!!" );
	}

	Session.Output( "======================================= Finished RefreshDynamicLegend at " + _BLOGGetDisplayDate() + "!" );

}

RefreshDynamicLegend();

!INC Local Scripts.EAConstants-JavaScript

/*
 * This code has been included from the default Diagram Script template.
 *
 * For all Elements on the selected diagram:
 *   For all TaggedValues for the curElement
 *      Mark a TaggedValue if it is a duplicate
 *   For all TaggedValues for the curElement
 *      Remove a TaggedValue if it is a duplicate
 *   Refresh Diagram
 *
 * NOTE: A TaggedValue is a duplicate if the Name AND Value are identical
 *
 * Script Name: DiagramDeleteDuplicateTaggedValues
 * Author:      J de Baat
 * Purpose:     Delete the duplicate TaggedValues of all elements occuring on the selected diagram
 * Date:        17-08-2023
 */


var DUPLICATE_PREFIX = "__DUPLICATE__";

/*
 * Test whether theTaggedValue is a Duplicate and remove it if it is
 */
function TaggedValueRemoveDuplicate( theElement, theTaggedValueIndex )
{

	// Cast the input values to objects so we get intellisense
	var curElement     as EA.Element;
	var curTaggedValue as EA.TaggedValue;
	var curElementTags as EA.Collection;
	curElement     = theElement;
	curElementTags = curElement.TaggedValues;

	// Check theTaggedValueIndex
	if ( curElementTags.Count < theTaggedValueIndex )
	{
		return -2;
	}

	// Get the curTaggedValue to test against
	curTaggedValue = curElementTags.GetAt( theTaggedValueIndex );

	// Check if the TaggedValue has a DUPLICATE_PREFIX
	if ( curTaggedValue.Name.startsWith( DUPLICATE_PREFIX ) )
	{
		Session.Output("curElement(" + curElement.Name + ") deleted DUPLICATE_PREFIX for curTaggedValue.item(" + theTaggedValueIndex + ").Name= " + curTaggedValue.Name + ", .Value= " + curTaggedValue.Value + "!!!" );
		curElementTags.Delete( theTaggedValueIndex );
		curElementTags.Refresh();
		return 1;
	} else {
		Session.Output("curElement(" + curElement.Name + ") found NO DUPLICATE_PREFIX for curTaggedValue.item(" + theTaggedValueIndex + ").Name= " + curTaggedValue.Name + ", .Value= " + curTaggedValue.Value + "!!!" );
		return 0;
	}

	return -1;
	//return ( (inputElement.ObjectType == 4) && (inputElement.Subtype == 76) );

}

/*
 * Test whether theTaggedValue is a Duplicate in theElement
 * Return results:	-2	theTaggedValueIndex too large
 * 					-1	theTaggedValueIndex NOT a duplicate
 * 					i	theTaggedValueIndex IS a duplicate
 */
function TaggedValueCheckDuplicate( theElement, theTaggedValueIndex )
{

	// Cast the input values to objects so we get intellisense
	var curElement     as EA.Element;
	var curTaggedValue as EA.TaggedValue;
	var curElementTags as EA.Collection;
	curElement     = theElement;
	curElementTags = curElement.TaggedValues;

	// Check theTaggedValueIndex
	if ( curElementTags.Count < theTaggedValueIndex )
	{
		return -2;
	}

	// Get the curTaggedValue to test against
	curTaggedValue = curElementTags.GetAt( theTaggedValueIndex );

	// Check all previous element tags for duplicate
	for ( var i = 0 ; i < theTaggedValueIndex ; i++ )
	{
		var testTaggedValue as EA.TaggedValue;
		testTaggedValue = curElementTags.GetAt( i );
		if ( (curTaggedValue.Name == testTaggedValue.Name) && (curTaggedValue.Value == testTaggedValue.Value) ) 
		{
			testTaggedValue.Name = DUPLICATE_PREFIX + testTaggedValue.Name;
			testTaggedValue.Update();
			return i;
		}
		//Session.Output("COMPARED curElement(" + curElement.Name + ")(" + curElementTags.Count + ") found curTaggedValue.Name= " + curTaggedValue.Name + ", Value= " + curTaggedValue.Value + ", PropertyGUID= " + curTaggedValue.PropertyGUID + "!!!" );
	}

	return -1;

}

/*
 * Get all TaggedValues for theTaggedValueObjectID from the t_objectproperties table
 */
function GetTaggedValueWithParameter( theTaggedValueParameter )
{

	// Get the TaggedValues registered for theTaggedValueParameter
	var strSQLQuery = "select * from t_objectproperties"
                      + " where t_objectproperties.PropertyID = '" + theTaggedValueParameter + "'"
                      + " order by t_objectproperties.Property";
	var sqlResponse = Repository.SQLQuery( strSQLQuery );

	// Convert the sqlResponse from XML to an array of TaggedValues
	var arrResponse = convertXMLtoTagNameArray( sqlResponse, "Property" );

	return arrResponse;

}

/*
 * Get all TaggedValues for theTaggedValueObjectID from the t_objectproperties table
 */
function GetTaggedValuesForElement( theTaggedValueObjectID )
{

	// Get all the TaggedValues registered for theTaggedValueObjectID
	var strSQLQuery = "select * from t_objectproperties"
                      + " where t_objectproperties.Object_ID = '" + theTaggedValueObjectID + "'"
                      + " order by t_objectproperties.Property";
	var sqlResponse = Repository.SQLQuery( strSQLQuery );

	// Convert the sqlResponse from XML to an array of TaggedValues
	var arrResponse = convertXMLtoTagNameArray( sqlResponse, "PropertyID" );

	return arrResponse;

}

/*
 * Extract an array from the XML resultset of an SQLQuery based on the xmlTagName
 */
function convertXMLtoTagNameArray( xmlString, xmlTagName )
{

	var xmlDOM = new COMObject( "MSXML2.DOMDocument" );
	xmlDOM.validateOnParse = false;
	xmlDOM.async = false;
	if ( xmlDOM.loadXML( xmlString ) ){
		var nodeList = xmlDOM.documentElement.selectNodes( '//' + xmlTagName );
		if ( nodeList.length > 0 ) {
			return nodeList;
		}
	}

	return false;

}

/*
 * Check the TaggedValues of theElement provided as parameter
 */
function CheckTaggedValuesElement( theElement )
{

	// Cast theElement to EA.Element so we get intellisense
	var curElement as EA.Element;
	var curElementTags as EA.Collection;
	curElement = theElement;
	curElementTags = curElement.TaggedValues;

	// List all element tags
	for ( var i = 0 ; i < curElementTags.Count ; i++ )
	{
		var curTaggedValue as EA.TaggedValue;
		curTaggedValue = curElementTags.GetAt( i );
		strResult = TaggedValueCheckDuplicate( curElement, i );
		Session.Output("curElement(" + curElement.Name + ")(" + curElementTags.Count + ") found strResult= " + strResult + " for curTaggedValue.Name= " + curTaggedValue.Name + ", Value= " + curTaggedValue.Value + ", PropertyGUID= " + curTaggedValue.PropertyGUID + "!!!" );
	}

	curElementTags.Refresh();
	arrElementTaggedValues = GetTaggedValuesForElement( curElement.ElementID );

	// Process the arrElementTaggedValues found
	if ( arrElementTaggedValues.length > 0 ) {

		// Add all getLegendPropString found for all strLegendTaggedValues
		for ( var i = arrElementTaggedValues.length - 1 ; i >= 0 ; i-- ) {
			// Test the TaggedValues found
			strResult = TaggedValueRemoveDuplicate( curElement, i );
			// Session.Output("curElement(" + curElement.Name + ")(" + arrElementTaggedValues.length + ") found TaggedValues.item(" + i + ")= " + arrElementTaggedValues.item(i).text + ", strResult= " + strResult + "!!!" );
		}

	} else {
		Session.Output("curElement(" + curElement.Name + ") found NO valid arrElementTaggedValues!!!" );
	}

}

/*
 * Diagram Script main function
 */
function DiagramDeleteDuplicateTaggedValues()
{
	// Get a reference to the current diagram
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();

	Session.Output("+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++" );

	if ( currentDiagram != null )
	{
		Session.Output("Selected Diagram(DiagramID: " + currentDiagram.DiagramID + ") Name= " + currentDiagram.Name );

		// Get a reference to any selected connector/objects
		var diagramObjects as EA.Collection;
		var currentElement as EA.Element;
		diagramObjects = currentDiagram.DiagramObjects;

		// Check whether this diagram has any objects in it
		if ( diagramObjects.Count > 0 )
		{
			Session.Output("Selected diagramObjects.Count: " + diagramObjects.Count );
			// One or more diagram objects are selected
			for ( var i = 0 ; i < diagramObjects.Count ; i++ )
			{
				Session.Output("..........................................................................................." );

				// Process the currentDiagramElement
				var currentDiagramElement as EA.Element;
				var currentElement as EA.Element;
				currentDiagramElement = diagramObjects.GetAt( i );
				currentElement = Repository.GetElementByID( currentDiagramElement.ElementID );

				// Check the TaggedValues of the currentElement
				CheckTaggedValuesElement( currentElement );
			}

			// Reload diagram when all processing is done
			Repository.ReloadDiagram( currentDiagram.DiagramID );
		}
		else
		{
			// No objects on this diagram
			Session.Output("No objects on this diagram" );
		}
	}
	else
	{
		Session.Prompt( "This script requires a diagram to be visible.", promptOK)
	}

	Session.Output("===========================================================================================" );

}

DiagramDeleteDuplicateTaggedValues();

