/*
 * Get and check the global variables for an IDB Diagram Script
 */
function GetAndCheckDiagram()
{

	// Prepare some global variables
	objGlobalPackage = null;
	objGlobalDiagram = null;

	// Get a reference to the current diagram
	objGlobalDiagram = Repository.GetCurrentDiagram();

	if ( objGlobalDiagram != null )
	{
		strMessage = "Found Diagram : " + objGlobalDiagram.Name + "!";
		BLOGTrace( strMessage );

		// Get a reference to the parent package of the current diagram
		objGlobalPackage = Repository.GetPackageByID( objGlobalDiagram.PackageID );
		strMessage = "Found " + objGlobalPackage.Name + " as parent package of objGlobalDiagram " + objGlobalDiagram.Name + " !";
		BLOGTrace( strMessage );

	}
	else
	{
		Session.Prompt( "This script requires a diagram to be visible.", promptOK)
	}

	//	Check objGlobalPackage and objGlobalDiagram again
	if ( ( objGlobalPackage == null ) || ( objGlobalDiagram == null ) ) {
		BLOGError( "Both objGlobalPackage AND objGlobalDiagram should be available!" );
		return false;
	}

	return true;

}

