	curNumElements = ProcessPackage( objGlobalEAPackage, 0 );
	Session.Output("ImExExportPackageElements Processed objGlobalEAPackage( " + objGlobalEAPackage.Name + " ) for NumElements = " + curNumElements + "!!!" );

