	curNumConnectors = ProcessPackage( objGlobalEAPackage, 0 );
	Session.Output("ImExExportPackageConnectors Processed objGlobalEAPackage( " + objGlobalEAPackage.Name + " ) and newNumConnectors = " + curNumConnectors + "!!!" );

